// TASK-0045 — V1 Brain Identity Editor, product acceptance in real WebView2.
// No simulated DOM, no alternate renderer, no personal data: the trees under test were
// generated by task0045-seed-proof.py and die with the proof root.
//
// The claim under test (`DEC-0043` §7): the name, the colour and the icon of ONE brain are edited
// through the interface, and nothing else moves — not the other brains (two of them read the very
// same folder), not the source, not the Index, not the journal, not the resume state of any
// brain — and the new identity is what comes back after a REAL close and relaunch.
//
//   phase 1  (process 1)  three brains, each given its own resume state through real clicks;
//                         all three composed; brain A edited with the KEYBOARD (real key events),
//                         brain B edited with the mouse, brain C: cancel with Escape and a refused
//                         entry, both leaving it bit for bit; the backend's own refusals probed;
//                         after every step: every other brain, the source, the Index, the journal
//                         and the resume records compared, and the product's own IPC calls read
//                         from the wire (only `map_brain_update` may be a write).
//   (real close of the application)
//   phase 2  (process 2)  the last active brain (A) comes back ALONE with its NEW identity and its
//                         resume state; B and C are visited, each exactly what it was; nothing
//                         rewrote the catalogue at boot; the editor reopens on the persisted values.
//
// What is compared is LOGICAL values: the catalogue read back (`map_brains`), the chips and the
// territory labels on the real screen, the resume records, revisions, journal totals, and a SHA-256
// of every file and directory name under both roots.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readdir, readFile, stat, writeFile } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join, relative } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
const phase = Number(process.argv[4]);
assert(/^task0045-[a-f0-9]+$/.test(variant));
assert([1, 2].includes(phase));

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const IDS = { A: seed.brainA, B: seed.brainB, C: seed.brainC };
const KEYS_OF = { [seed.brainA]: "A", [seed.brainB]: "B", [seed.brainC]: "C" };
const ROOTS = [seed.rootShared, seed.rootSolo];
const SEED = { A: seed.seed.a, B: seed.seed.b, C: seed.seed.c };
const proofRoot = join(".filetopo-sandbox", variant);
const readJson = async (name) => JSON.parse(await readFile(join(proofRoot, name), "utf8"));
const writeJson = (name, value) => writeFile(join(proofRoot, name), JSON.stringify(value, null, 1));

// ---- CDP attach --------------------------------------------------------------------
let target;
for (let n = 0; n < 150; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(100);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
// Every `map_*` IPC round trip, observed on the wire (CDP Network), in order, with its arguments.
// The harness's own `invoke` calls travel the same wire, so the windows in which the PRODUCT is
// judged are the ones in which the harness makes no call of its own.
const wireRequests = new Map();
const wireCalls = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.method === "Network.requestWillBeSent") {
    const url = event.params.request.url;
    const m = /\/(map_[a-z_]+)(?:[?#].*)?$/.exec(url);
    if (m && /ipc/.test(url) && event.params.request.method === "POST") {
      wireRequests.set(event.params.requestId, {
        command: m[1],
        body: event.params.request.postData ?? "",
        hasPostData: event.params.request.hasPostData === true,
        at: Date.now(),
      });
    }
  } else if (event.method === "Network.loadingFinished" && wireRequests.has(event.params.requestId)) {
    const request = wireRequests.get(event.params.requestId);
    request.bodyReady =
      request.body === "" && request.hasPostData
        ? send("Network.getRequestPostData", { requestId: event.params.requestId })
            .then((r) => {
              request.body = r.postData ?? "";
            })
            .catch(() => {})
        : Promise.resolve();
    wireCalls.push(request);
    wireRequests.delete(event.params.requestId);
  }
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) {
    throw new Error(
      r.exceptionDetails.exception?.description ?? r.exceptionDetails.exception?.value ?? JSON.stringify(r.exceptionDetails),
    );
  }
  return r.result.value;
}
async function until(expression, limit = 120000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
async function untilTrue(description, predicate, limit = 120000, interval = 150) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await predicate()) return;
    await pause(interval);
  }
  throw new Error(`timeout: ${description}`);
}
const exposedPayloads = [];
const invoke = async (command, args = {}) => {
  exposedPayloads.push(JSON.stringify(args));
  const result = await evaluate(`window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`);
  exposedPayloads.push(JSON.stringify(result ?? null));
  return result;
};
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");
await send("Network.enable", { maxTotalBufferSize: 64 * 1024 * 1024, maxResourceBufferSize: 16 * 1024 * 1024 });

// ---- real input ---------------------------------------------------------------------
const centerOf = (selector) =>
  evaluate(`(() => {
    const e = document.querySelector(${JSON.stringify(selector)});
    if (!e) return null;
    e.scrollIntoView?.({ block: 'center', inline: 'center' });
    const r = e.getBoundingClientRect();
    const x = r.x + r.width / 2;
    const y = r.y + r.height / 2;
    const top = document.elementFromPoint(x, y);
    return {
      x, y, w: r.width, h: r.height,
      hit: !!top && (e === top || e.contains(top) || top.contains(e)),
      topmost: top ? (top.getAttribute('data-testid') || top.tagName) : null,
    };
  })()`);
/** One real left click (move, press, release) at the middle of the element. */
async function click(selector) {
  const box = await centerOf(selector);
  assert(box && box.w > 0 && box.h > 0, `click: nothing clickable at ${selector}`);
  assert(box.hit, `click: ${selector} is covered by ${box.topmost} at (${Math.round(box.x)}, ${Math.round(box.y)})`);
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: box.x, y: box.y });
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x: box.x, y: box.y, button: "left", buttons: 1, clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: box.x, y: box.y, button: "left", buttons: 0, clickCount: 1 });
  await pause(200);
}
async function wheel(fx, fy, deltaY, count, gapMs = 15) {
  const box = await centerOf('[data-testid="composed-canvas"]');
  const x = box.x - box.w / 2 + box.w * fx;
  const y = box.y - box.h / 2 + box.h * fy;
  for (let i = 0; i < count; i += 1) {
    await send("Input.dispatchMouseEvent", { type: "mouseWheel", x, y, deltaX: 0, deltaY });
    if (gapMs) await pause(gapMs);
  }
}
async function drag(fx, fy, dx, dy) {
  const box = await centerOf('[data-testid="composed-canvas"]');
  const x = box.x - box.w / 2 + box.w * fx;
  const y = box.y - box.h / 2 + box.h * fy;
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", buttons: 1, clickCount: 1 });
  for (let step = 1; step <= 12; step += 1) {
    await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: x + (dx * step) / 12, y: y + (dy * step) / 12, buttons: 1 });
    await pause(20);
  }
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: x + dx, y: y + dy, button: "left", buttons: 0, clickCount: 1 });
  await pause(200);
}
// Real key events, dispatched through the browser's input pipeline (CDP `Input.dispatchKeyEvent`).
const SPECIAL = {
  Tab: { code: "Tab", vk: 9 },
  Enter: { code: "Enter", vk: 13, text: "\r" },
  Escape: { code: "Escape", vk: 27 },
};
async function press(key) {
  const k = SPECIAL[key];
  await send("Input.dispatchKeyEvent", {
    type: "keyDown", key, code: k.code, windowsVirtualKeyCode: k.vk, nativeVirtualKeyCode: k.vk,
    ...(k.text ? { text: k.text, unmodifiedText: k.text } : {}),
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key, code: k.code, windowsVirtualKeyCode: k.vk, nativeVirtualKeyCode: k.vk });
  await pause(150);
}
async function selectAll() {
  await send("Input.dispatchKeyEvent", {
    type: "keyDown", modifiers: 2, key: "a", code: "KeyA", windowsVirtualKeyCode: 65, nativeVirtualKeyCode: 65, commands: ["selectAll"],
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", modifiers: 2, key: "a", code: "KeyA", windowsVirtualKeyCode: 65, nativeVirtualKeyCode: 65 });
}
async function typeText(text) {
  for (const ch of Array.from(text)) {
    await send("Input.dispatchKeyEvent", { type: "keyDown", key: ch, text: ch, unmodifiedText: ch });
    await send("Input.dispatchKeyEvent", { type: "keyUp", key: ch });
    await pause(25);
  }
  await pause(100);
}
/**
 * A key through the OPERATING SYSTEM's input path: the FileTopo window is brought to the foreground
 * and the key is sent with WScript.Shell, exactly as the earlier real-key proofs did.
 */
function osKey(keys) {
  const script = `
    Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class W { [DllImport("user32.dll")] public static extern void SwitchToThisWindow(IntPtr h, bool a); }'
    $p = Get-Process -Name filetopo -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 } | Sort-Object StartTime -Descending | Select-Object -First 1
    if ($null -eq $p) { Write-Output 'no-window'; exit 3 }
    [W]::SwitchToThisWindow($p.MainWindowHandle, $true)
    Start-Sleep -Milliseconds 700
    (New-Object -ComObject WScript.Shell).SendKeys('${keys}')
    Write-Output 'sent'`;
  const encoded = Buffer.from(script, "utf16le").toString("base64");
  const result = spawnSync("powershell", ["-NoProfile", "-NonInteractive", "-EncodedCommand", encoded], { encoding: "utf8", timeout: 30000 });
  return { ok: result.status === 0 && /sent/.test(result.stdout ?? ""), output: (result.stdout ?? "").trim() };
}

