const ALLOWED_DURING_AN_EDIT = new Set([
  "map_brain_update",
  // The inter-brain store answers with each brain's name and icon: it is re-read, never written.
  "map_cross_relations_open",
  "map_cross_relations_for_node",
]);
const wireWindow = async (from) => {
  await Promise.all(wireCalls.slice(from).map((call) => call.bodyReady));
  return wireCalls.slice(from);
};

/** Every claim of an edit, checked against what was known before it. */
async function assertEditEffects({ label, editedKey, before, after, expected, window }) {
  const problems = [];
  const eq = (name, a, b) => {
    if (!same(a, b)) problems.push(`${label}: ${name}: expected ${JSON.stringify(a)}, got ${JSON.stringify(b)}`);
  };
  for (const key of ["A", "B", "C"]) {
    if (key === editedKey) continue;
    // Bit for bit: every field of the untouched brains, including the ones that share a source.
    eq(`brain ${key} record`, before.records[key], after.records[key]);
  }
  const was = before.records[editedKey];
  const is = after.records[editedKey];
  eq(`brain ${editedKey} identity fields`, { displayName: expected.displayName, color: expected.color, icon: expected.icon }, {
    displayName: is.displayName, color: is.color, icon: is.icon,
  });
  for (const field of ["brainId", "sourceKind", "sourceRef", "sourceLabel", "position"]) eq(`brain ${editedKey}.${field}`, was[field], is[field]);
  eq("the source (every name, size, date and digest)", before.source, after.source);
  eq("the Index and the journal of every brain", before.index, after.index);
  eq("the resume record of every brain", before.resume, after.resume);
  eq("the active brain", before.catalogue.activeBrainId, after.catalogue.activeBrainId);
  const commands = window.map((call) => call.command);
  const foreign = commands.filter((command) => !ALLOWED_DURING_AN_EDIT.has(command));
  if (foreign.length > 0) problems.push(`${label}: the product sent ${foreign.join(", ")} during the edit`);
  const updates = window.filter((call) => call.command === "map_brain_update");
  if (updates.length !== 1) problems.push(`${label}: ${updates.length} map_brain_update on the wire, expected exactly 1`);
  else {
    const body = JSON.parse(updates[0].body || "{}");
    eq("the update body's keys", ["brainId", "color", "displayName", "icon"], Object.keys(body).sort());
    eq("the update names the edited brain only", IDS[editedKey], body.brainId);
  }
  assert.deepEqual(problems, [], problems.join("\n"));
}
/** What is on the real screen: the edited chip and label carry the new identity, the others do not. */
async function assertScreenIdentity({ label, records, mustShow = null }) {
  const s = await screenState();
  for (const key of ["A", "B", "C"]) {
    const chip = s.chips[IDS[key]];
    if (!chip) continue;
    const record = records[key];
    assert.equal(chip.name, record.displayName, `${label}: chip name of ${key}`);
    assert.equal(chip.icon, record.icon, `${label}: chip icon of ${key}`);
    assert.equal(chip.swatch, rgbOf(record.color), `${label}: chip colour of ${key}`);
  }
  // A territory title is only drawn while its header is on screen: every title that IS drawn must be
  // a current identity (a stale one fails), and the edited brain's own must be among them.
  const current = Object.values(records).map((r) => `${r.icon} ${r.displayName} · `);
  for (const title of s.territoryTitles) {
    assert(current.some((prefix) => title.startsWith(prefix)), `${label}: the territory title « ${title} » is not a current identity`);
  }
  if (mustShow) {
    const r = records[mustShow];
    assert(s.territoryTitles.some((t) => t.startsWith(`${r.icon} ${r.displayName} · `)), `${label}: the map's territory title of ${mustShow} reads « ${r.icon} ${r.displayName} » (drawn: ${JSON.stringify(s.territoryTitles)})`);
  }
  return s;
}

const results = {};
await until(`!!window.__TAURI_INTERNALS__`);
await waitApp();

// =====================================================================================
if (phase === 1) {
  // ---- 1 — baseline: Actualiser for A (a real click); B and C are indexed by the same command.
  await click('[data-testid="lifecycle-refresh"]');
  await untilTrue("A indexed and shown", async () => (await screenState()).nodeIds.length > 3, 120000);
  await invoke("map_refresh", { brainId: IDS.B });
  await invoke("map_refresh", { brainId: IDS.C });
  const start = await recordsOf();
  for (const key of ["A", "B", "C"]) {
    assert.equal(start[key].displayName, SEED[key].displayName, `${key} starts as seeded`);
    assert.equal(start[key].color, SEED[key].color);
    assert.equal(start[key].icon, SEED[key].icon);
  }
  assert.equal(start.A.sourceRef, start.C.sourceRef, "A and C share one source");
  assert.equal(start.A.sourceLabel, start.C.sourceLabel);
  assert.notEqual(start.A.brainId, start.C.brainId);
  assert.notEqual(start.A.sourceRef, start.B.sourceRef);
  const idx = await indexStates();
  assert.equal(idx.A.nodeCount, 15, "the shared folder has 15 entries");
  assert.equal(idx.C.nodeCount, 15, "and so does C, from its own Index");
  assert.equal(idx.B.nodeCount, 8);
  results.startingIdentities = Object.fromEntries(["A", "B", "C"].map((k) => [k, { displayName: start[k].displayName, color: start[k].color, icon: start[k].icon }]));

  // ---- 2 — each brain is given its own resume state through real interaction (TASK-0044)
  await selectByClick("A", "notes");
  await click('[data-testid="details-panel-toggle"]');
  await untilTrue("A panel hidden", async () => (await screenState()).panelVisible === false);
  await wheel(0.4, 0.4, -120, 8, 30);
  await settledRecord(IDS.A, (r) => r.selectedNodeId !== null && r.view !== null && r.detailsPanelVisible === false, "A state");
  await switchTo("B", "A");
  await selectByClick("B", "solo-fin.txt");
  await drag(0.55, 0.6, -70, -30);
  await settledRecord(IDS.B, (r) => r.selectedNodeId !== null && r.view !== null && r.detailsPanelVisible === true, "B state");
  await switchTo("C", "B");
  await selectByClick("C", "fin.txt");
  await wheel(0.7, 0.3, 60, 4, 30);
  await settledRecord(IDS.C, (r) => r.selectedNodeId !== null && r.view !== null, "C state");
  const givenStates = await resumeRecords();
  assert(!same(givenStates.A, givenStates.B) && !same(givenStates.B, givenStates.C) && !same(givenStates.A, givenStates.C), "the three resume states differ");
  results.resumeStatesGiven = givenStates;

  // ---- 3 — all three brains on the screen; the editor works on the FOCUSED one
  await addToView("A");
  await addToView("B");
  let s = await screenState();
  assert.deepEqual([...s.chipIds].sort(), [IDS.A, IDS.B, IDS.C].sort(), "the three brains are composed");

  // ---- 4 — EDIT 1: brain A, with the KEYBOARD
  await focusChip("A");
  await settledRecord(IDS.A, () => true, "A quiet");
  const before1 = await fullSnapshot();
  const edit1 = { displayName: "Alix révisée", color: "#c0392b", icon: "★" };
  const mark1 = wireCalls.length;
  await click('[data-testid="brain-identity-open"]');
  await untilTrue("the editor is open on A", async () => (await formState()).open);
  let form = await formState();
  assert.equal(form.brainId, IDS.A, "the form is bound to the focused brain");
  assert(form.title.includes(SEED.A.displayName), `the title names the brain being edited (${form.title})`);
  assert.equal(form.name, SEED.A.displayName, "opens on the catalogue's name");
  assert.equal(form.color, SEED.A.color.toLowerCase(), "and its colour");
  assert.equal(form.icon, SEED.A.icon, "and its icon");
  assert.equal(form.inputs, 3, "three fields");
  assert.deepEqual(form.labels, ["Nom", "Couleur", "Icône"]);
  assert.deepEqual(form.buttons, ["Enregistrer", "Annuler"]);
  assert(!/sourceRef|sourceLabel|real-|shared|solo|\\/.test(form.formText), "no source, id or path in the form");
  assert.equal(form.focus, "brain-identity-name", "the focus is on the name field");
  await selectAll();
  await typeText(edit1.displayName);
  await press("Tab");
  assert.equal((await formState()).focus, "brain-identity-color", "Tab reaches the colour field");
  await setColour(edit1.color);
  await press("Tab");
  assert.equal((await formState()).focus, "brain-identity-icon", "Tab reaches the icon field");
  await selectAll();
  await typeText(edit1.icon);
  form = await formState();
  assert.equal(form.name, edit1.displayName);
  assert.equal(form.icon, edit1.icon);
  assert.equal(form.color, edit1.color);
  // Nothing is published before Enregistrer: the chip still shows the old identity.
  s = await screenState();
  assert.equal(s.chips[IDS.A].name, SEED.A.displayName, "no optimistic change while typing");
  // The save itself is a key: the operating system's, when the window can be brought forward.
  const os = osKey("{ENTER}");
  let saveKey = "os";
  try {
    await untilTrue("the form closed after Enter", async () => !(await formState()).open, os.ok ? 8000 : 500);
  } catch {
    saveKey = "cdp";
    await press("Enter");
    await untilTrue("the form closed after Enter (CDP)", async () => !(await formState()).open, 20000);
  }
  await pause(900);
  const window1 = await wireWindow(mark1);
  const after1 = await fullSnapshot();
  await assertEditEffects({ label: "edit 1 (keyboard, brain A)", editedKey: "A", before: before1, after: after1, expected: edit1, window: window1 });
  await assertScreenIdentity({ label: "edit 1", records: after1.records, mustShow: "A" });
  assert.equal(((await formState()).focus), "brain-identity-open", "the focus went back to the gesture that opened the form");
  results.edit1 = {
    how: "brain A, the form walked with Tab and saved with Enter; name and icon typed with real key events",
    saveKeyPath: saveKey === "os" ? "operating-system key (WScript.Shell SendKeys, window brought forward)" : "browser input pipeline (CDP Input.dispatchKeyEvent); the operating-system key could not be delivered",
    osKeyOutput: os.output,
    colourSetThrough: "the page's value setter plus the real input event (a native colour picker cannot be driven)",
    wire: window1.map((call) => call.command),
    result: { displayName: after1.records.A.displayName, color: after1.records.A.color, icon: after1.records.A.icon },
  };
  const frozenC = start.C;

  // ---- 5 — EDIT 2: brain B, with the MOUSE
  await focusChip("B");
  await settledRecord(IDS.B, () => true, "B quiet");
  const before2 = await fullSnapshot();
  const edit2 = { displayName: "Basile bis", color: "#16a085", icon: "◈" };
  const mark2 = wireCalls.length;
  await click('[data-testid="brain-identity-open"]');
  await untilTrue("the editor is open on B", async () => (await formState()).open);
  assert.equal((await formState()).brainId, IDS.B);
  await click('[data-testid="brain-identity-name"]');
  await selectAll();
  await typeText(edit2.displayName);
  await setColour(edit2.color);
  await click('[data-testid="brain-identity-icon"]');
  await selectAll();
  await typeText(edit2.icon);
  await click('[data-testid="brain-identity-save"]');
  await untilTrue("the form closed after Enregistrer", async () => !(await formState()).open, 20000);
  await pause(900);
  const window2 = await wireWindow(mark2);
  const after2 = await fullSnapshot();
  await assertEditEffects({ label: "edit 2 (mouse, brain B)", editedKey: "B", before: before2, after: after2, expected: edit2, window: window2 });
  // A keeps what edit 1 gave it; C is still what it was seeded as.
  assert(same(before2.records.A, after2.records.A), "A keeps its edited identity");
  assert(same(after2.records.C, frozenC), "C is still bit for bit what it was");
  await assertScreenIdentity({ label: "edit 2", records: after2.records, mustShow: "B" });
  results.edit2 = { how: "brain B, mouse and typed text, saved with the Enregistrer button", wire: window2.map((call) => call.command), result: { displayName: after2.records.B.displayName, color: after2.records.B.color, icon: after2.records.B.icon } };

  // ---- 6 — brain C: cancel with Escape, then an entry the form refuses; nothing moves
  await focusChip("C");
  await settledRecord(IDS.C, () => true, "C quiet");
  const before3 = await fullSnapshot();
  const mark3 = wireCalls.length;
  await click('[data-testid="brain-identity-open"]');
  await untilTrue("the editor is open on C", async () => (await formState()).open);
  assert.equal((await formState()).brainId, IDS.C);
  await selectAll();
  await typeText("Brouillon jeté");
  await press("Escape");
  await untilTrue("Escape closed the form", async () => !(await formState()).open, 10000);
  await click('[data-testid="brain-identity-open"]');
  await untilTrue("the editor reopened on C", async () => (await formState()).open);
  form = await formState();
  assert.equal(form.name, SEED.C.displayName, "reopening shows the catalogue, not the discarded draft");
  await click('[data-testid="brain-identity-name"]');
  await selectAll();
  await send("Input.dispatchKeyEvent", { type: "keyDown", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 });
  assert.equal((await formState()).name, "", "the name field is empty");
  await press("Enter");
  await untilTrue("the form explains the entry", async () => (await formState()).problem !== null, 10000);
  form = await formState();
  assert(/1 à 80/.test(form.problem), `the message states the bound (${form.problem})`);
  assert.equal(form.open, true, "the form stays open");
  await press("Escape");
  await untilTrue("closed", async () => !(await formState()).open, 10000);
  await pause(600);
  const window3 = await wireWindow(mark3);
  const after3 = await fullSnapshot();
  assert.equal(window3.filter((call) => call.command === "map_brain_update").length, 0, "no update was sent for a cancel or an invalid entry");
  assert(same(before3.records, after3.records), "the catalogue is exactly what it was");
  assert(same(before3.resume, after3.resume) && same(before3.index, after3.index) && same(before3.source, after3.source));
  results.cancelAndRefusedEntry = { updatesOnTheWire: 0, wire: window3.map((call) => call.command), catalogueUnchanged: true };

  // ---- 7 — the backend's own refusals, asked directly: each one is an error, nothing is written
  const beforeRefusals = await invoke("map_brains");
  const refused = [];
  for (const [label, args] of [
    ["unknown brain", { brainId: "real-inconnu", displayName: "X", color: "#112233", icon: "x" }],
    ["empty name", { brainId: IDS.C, displayName: "   ", color: "#112233", icon: "x" }],
    ["81-character name", { brainId: IDS.C, displayName: "n".repeat(81), color: "#112233", icon: "x" }],
    ["colour without #", { brainId: IDS.C, displayName: "Ok", color: "112233", icon: "x" }],
    ["colour not hexadecimal", { brainId: IDS.C, displayName: "Ok", color: "#12345g", icon: "x" }],
    ["three-scalar icon", { brainId: IDS.C, displayName: "Ok", color: "#112233", icon: "abc" }],
    ["empty icon", { brainId: IDS.C, displayName: "Ok", color: "#112233", icon: "" }],
  ]) {
    let message = null;
    try {
      await invoke("map_brain_update", args);
    } catch (error) {
      message = String(error.message ?? error);
    }
    assert(message !== null, `the backend accepted a ${label}`);
    refused.push({ case: label, refused: true });
  }
  assert(same(beforeRefusals, await invoke("map_brains")), "seven refusals wrote nothing");
  results.backendRefusals = refused;

  // ---- 8 — close on a known state: A is the active brain, every record is what the restart must return
  await focusChip("A");
  await settledRecord(IDS.A, () => true, "A quiet at close");
  const atClose = await fullSnapshot();
  assert.equal(atClose.catalogue.activeBrainId, IDS.A, "A is the active brain at close");
  assert(same(atClose.records.C, frozenC), "C is unchanged at close");
  assert.equal(atClose.records.A.displayName, edit1.displayName);
  assert.equal(atClose.records.B.displayName, edit2.displayName);
  results.atClose = { records: atClose.records, resume: atClose.resume, index: atClose.index, source: atClose.source, activeBrainId: atClose.catalogue.activeBrainId };
  // The three identities are three different things after the edits.
  const identities = ["A", "B", "C"].map((k) => JSON.stringify([atClose.records[k].displayName, atClose.records[k].color, atClose.records[k].icon]));
  assert.equal(new Set(identities).size, 3);
  results.aAndCStillShareTheirSource = atClose.records.A.sourceRef === atClose.records.C.sourceRef && atClose.records.A.sourceLabel === atClose.records.C.sourceLabel;
  assert(results.aAndCStillShareTheirSource);
  await assertConfidential();
  await writeJson("phase1.json", results);
  await writeJson("phase1-fatal-count.json", fatal.length);
  console.log(JSON.stringify({ ok: true, phase }));
  process.exit(fatal.length === 0 ? 0 : 1);
}

// =====================================================================================
if (phase === 2) {
  const before = await readJson("phase1.json");
  const closed = before.atClose;
  // The last active brain (A) comes back ALONE.
  await untilTrue("A alone", shownAlone(IDS.A), 90000);
  results.reopenedAlone = "A";
  await pause(1200);
  // Nothing at boot rewrote the catalogue: the product sent no update of any brain.
  const bootWrites = wireCalls.filter((call) => call.command === "map_brain_update");
  assert.equal(bootWrites.length, 0, "the product sent no map_brain_update at boot");
  const now = await fullSnapshot();
  for (const key of ["A", "B", "C"]) {
    assert(same(closed.records[key], now.records[key]), `brain ${key}: the whole record is exactly what it was at close`);
  }
  assert.equal(now.catalogue.activeBrainId, closed.activeBrainId);
  assert(same(closed.source, now.source), "the source is unchanged across the restart");
  assert(same(closed.index, now.index), "revision, node count and journal total of every brain are unchanged");
  assert(same(closed.resume, now.resume), "the resume record of every brain is exactly what it was at close");
  // The identity on the real screen is the persisted one, and not the seed's.
  const shown = await assertScreenIdentity({ label: "after the restart", records: now.records, mustShow: "A" });
  assert.notEqual(shown.chips[IDS.A].name, SEED.A.displayName, "the seed did not put the default name back");
  assert.equal(shown.chips[IDS.A].name, "Alix révisée");
  assert.equal(shown.chips[IDS.A].icon, "★");
  assert.equal(shown.chips[IDS.A].swatch, rgbOf("#c0392b"));
  assert.equal(shown.chips[IDS.A].stateWord, "actif", "the active brain is said in words, not only in colour");
  // TASK-0044 still holds: A reopens where it was left.
  assert.equal(shown.selectedId, closed.resume.A.selectedNodeId, "A's selection came back");
  assert.equal(shown.panelVisible, closed.resume.A.detailsPanelVisible, "A's panel state came back");
  assert(shown.labels.length > 0 && shown.labels.every((label) => label.startsWith("Alix révisée ·")), "every node of A is labelled with its new name");
  results.afterRestart = { A: { name: shown.chips[IDS.A].name, icon: shown.chips[IDS.A].icon, swatch: shown.chips[IDS.A].swatch }, selectedNodeId: shown.selectedId, panelVisible: shown.panelVisible };

  // The editor reopens on the persisted values.
  await click('[data-testid="brain-identity-open"]');
  await untilTrue("editor open", async () => (await formState()).open);
  const form = await formState();
  assert.equal(form.brainId, IDS.A);
  assert.equal(form.name, "Alix révisée");
  assert.equal(form.color, "#c0392b");
  assert.equal(form.icon, "★");
  await press("Escape");
  await untilTrue("editor closed", async () => !(await formState()).open);
  results.editorReopensOnPersistedValues = true;

  // B and C, brought in one after the other: their own identity and their own resume state.
  await switchTo("B", "A");
  let s = await assertScreenIdentity({ label: "brain B after the restart", records: now.records, mustShow: "B" });
  assert.equal(s.chips[IDS.B].name, "Basile bis");
  assert.equal(s.chips[IDS.B].icon, "◈");
  assert.equal(s.selectedId, closed.resume.B.selectedNodeId, "B's selection came back");
  assert.equal(s.panelVisible, closed.resume.B.detailsPanelVisible);
  await switchTo("C", "B");
  s = await assertScreenIdentity({ label: "brain C after the restart", records: now.records, mustShow: "C" });
  assert.equal(s.chips[IDS.C].name, SEED.C.displayName, "C was never edited: still its own seed identity");
  assert.equal(s.chips[IDS.C].icon, SEED.C.icon);
  assert.equal(s.selectedId, closed.resume.C.selectedNodeId, "C's selection came back");
  await pause(800);
  const end = await fullSnapshot();
  assert(["A", "B", "C"].every((k) => same(closed.records[k], end.records[k])),"visiting the brains changed no identity");
  assert(same(closed.source, end.source), "the source is still unchanged");
  assert(same(closed.index, end.index), "no Index revision and no journal event appeared");
  assert.equal(wireCalls.filter((call) => call.command === "map_brain_update").length, 0, "the product never wrote an identity during phase 2");
  results.afterVisiting = { sourceUnchanged: true, indexAndJournalUnchanged: true, identitiesUnchanged: true };
  await assertConfidential();
  await writeJson("phase2.json", results);
  await writeJson("phase2-fatal-count.json", fatal.length);
  console.log(JSON.stringify({ ok: true, phase }));
  process.exit(fatal.length === 0 ? 0 : 1);
}
